parameters.jsCode:
const participantes = $("Enriquecer contas e contatos do participante").all();
const tarefas = $("Enriquecer taxonomias da tarefa").all();

// ID da taxonomia Webhook na tua base do Notion.
const WEBHOOK_ID = "3d9a704c-c5f1-8174-af42-c69d958f913c";

const normalizarId = (id) =>
  String(id ?? "").replace(/-/g, "").toLowerCase();

if (participantes.length !== 1 || tarefas.length !== 1) {
  throw new Error("Esperado exatamente um participante e uma tarefa.");
}

const participante = participantes[0].json;
const tarefa = tarefas[0].json;

// Confere se o participante é responsável pela tarefa.
const responsaveis =
  tarefa.properties?.["👥 Responsável"]?.relation ?? [];

if (!responsaveis.some(
  (r) => normalizarId(r.id) === normalizarId(participante.id)
)) {
  throw new Error("O participante informado não é responsável pela tarefa.");
}

// Usa as páginas de taxonomia enriquecidas para identificar a função.
const taxonomias = tarefa["🏷️ Taxonomia"];

if (!Array.isArray(taxonomias)) {
  throw new Error("As taxonomias da tarefa não foram enriquecidas.");
}

const funcoes = taxonomias.filter(
  (taxonomia) =>
    taxonomia.properties?.Natureza?.select?.name === "Função"
);

if (funcoes.length !== 1) {
  throw new Error(
    `A tarefa precisa ter exatamente uma taxonomia de natureza Função. Encontradas: ${funcoes.length}.`
  );
}

const funcaoId = normalizarId(funcoes[0].id);
const contatos = participante["📇 Contas e Contatos"];

if (!Array.isArray(contatos)) {
  throw new Error("As contas e contatos do participante não foram enriquecidas.");
}

// O mesmo contato precisa conter as duas taxonomias.
const encontrados = contatos.filter((contato) => {
  const ids = new Set(
    (contato.properties?.["🏷️ Taxonomias"]?.relation ?? [])
      .map((taxonomia) => normalizarId(taxonomia.id))
  );

  return ids.has(normalizarId(WEBHOOK_ID)) && ids.has(funcaoId);
});

if (encontrados.length !== 1) {
  throw new Error(
    `Esperado um contato com Webhook e a função da tarefa. Encontrados: ${encontrados.length}. Tarefa: ${tarefa.id}. Participante: ${participante.id}.`
  );
}

return [{ json: encontrados[0] }];

